func:
// Extract payload or default
let data = msg.payload || {};

// Machine Name: from payload or URL param or default
let machine = data.machine_name || (msg.req.params && msg.req.params.machine) || "MC-UNKNOWN";
let line = data.line_name || "Line-01";
let value = data.value !== undefined ? String(data.value).trim() : "";
let prevValue = data.previous_value !== undefined && data.previous_value !== null ? String(data.previous_value).trim() : null;
let timestamp = data.timestamp || new Date().toISOString().slice(0, 19).replace('T', ' ');

// Basic validation
if (!value) {
    msg.statusCode = 400;
    msg.payload = {
        status: "ERROR",
        message: "Value field is required and cannot be empty"
    };
    node.error("Received empty OCR value from machine: " + machine, msg);
    return [null, msg, null];
}

// Store normalized data
msg.ocr_data = {
    machine_name: machine,
    line_name: line,
    value: value,
    previous_value: prevValue,
    timestamp: timestamp
};

// 1. Immediate HTTP Response (Output 1)
let responseMsg = {
    _msgid: msg._msgid,
    req: msg.req,
    res: msg.res,
    statusCode: 200,
    payload: {
        status: "SUCCESS",
        machine_name: machine,
        line_name: line,
        detected_value: value,
        previous_value: prevValue,
        received_at: timestamp
    }
};

// 2. MySQL / SQL Query 1: Insert into Historical Logs (Output 2)
let insertLogMsg = {
    _msgid: msg._msgid,
    topic: "INSERT INTO machine_ocr_logs (machine_name, line_name, detected_value, previous_value, captured_at) VALUES (?, ?, ?, ?, ?);",
    payload: [machine, line, value, prevValue, timestamp],
    ocr_data: msg.ocr_data
};

// 3. MySQL / SQL Query 2: Upsert into Live Current Status (Output 3)
let upsertStatusMsg = {
    _msgid: msg._msgid,
    topic: "INSERT INTO machine_current_status (machine_name, line_name, latest_value, previous_value, last_updated) VALUES (?, ?, ?, ?, ?) ON DUPLICATE KEY UPDATE latest_value=VALUES(latest_value), previous_value=VALUES(previous_value), last_updated=VALUES(last_updated);",
    payload: [machine, line, value, prevValue, timestamp],
    ocr_data: msg.ocr_data
};

// 4. Debug output for node status
node.status({ fill: "green", shape: "dot", text: machine + " (" + line + "): " + value });

// Return: [HTTP Response, Insert Log, Upsert Status]
return [responseMsg, insertLogMsg, upsertStatusMsg];
